export interface ConnectorConfig {
  /** Asana Personal Access Token (PAT) for API authentication. */
  asanaAccessToken: string
  /** The Asana workspace GID where tasks will be created. */
  workspaceGid: string
  /** Optional fetch implementation for testing or custom environments. */
  fetch?: typeof fetch
}

export interface JotformSubmissionPayload {
  /** Title of the submitted form, used as the Asana task name. */
  formTitle: string
  /** Internal Jotform submission identifier. */
  submissionId: string
  /** Dynamic form fields keyed by their Jotform field ID (e.g., field_123). */
  [key: `field_${string}`]: string | undefined
}

export interface CreateTaskResult {
  /** The GID of the created Asana task. */
  taskGid: string
  /** The name of the created task (mirrors formTitle). */
  taskName: string
  /** The description/notes of the created task. */
  taskNotes: string
}

async function handle(
  payload: JotformSubmissionPayload,
  config: ConnectorConfig
): Promise<CreateTaskResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.formTitle || typeof payload.formTitle !== 'string') {
    throw new Error('Missing required field: formTitle')
  }

  const fieldEntries = Object.entries(payload).filter(([key]) => key.startsWith('field_'))
  if (fieldEntries.length === 0) {
    throw new Error('No form fields found in payload (expected at least one field_* key)')
  }

  const descriptionLines = fieldEntries.map(([key, value]) => {
    const fieldId = key.replace('field_', '')
    return `Field ${fieldId}: ${value ?? ''}`
  })
  const taskNotes = descriptionLines.join('\n')

  const requestBody = {
    data: {
      name: payload.formTitle,
      notes: taskNotes,
      workspace: config.workspaceGid
    }
  }

  const response = await fetchImpl('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.asanaAccessToken}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json'
    },
    body: JSON.stringify(requestBody)
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(
      `Asana API error: ${response.status} ${response.statusText} at POST https://app.asana.com/api/1.0/tasks - ${errorText}`
    )
  }

  const result = await response.json() as { data: { gid: string; name: string; notes: string } }
  return {
    taskGid: result.data.gid,
    taskName: result.data.name,
    taskNotes: result.data.notes
  }
}

